import { createContext, useContext, useState, useEffect } from "react";
import { AuthContext } from "./AuthContext";
import { transformUserData } from "../utils/transformUserData";

export const UserContext = createContext();

export const UserProvider = ({ children }) => {
  const { token } = useContext(AuthContext);

  const [userData, setUserData] = useState(null);
  const [loading, setLoading] = useState(true);

useEffect(() => {
  // Tant que le token n'est pas encore chargé depuis localStorage → on attend
  if (token === null) return;

  // Si pas de token → utilisateur non connecté
  if (!token) {
    setUserData({
      profile: {},
      statistics: {},
      sessions: [],
    });
    setLoading(false);
    return;
  }

  const fetchUserData = async () => {
    try {
      setLoading(true);

      // 1) Profil + statistiques
      const infoRes = await fetch("http://localhost:8000/api/user-info", {
        method: "GET",
        headers: { Authorization: `Bearer ${token}` },
      });

      // 2) Sessions (toutes les sessions)
      const activityRes = await fetch(
        "http://localhost:8000/api/user-activity?startWeek=1900-01-01&endWeek=2100-01-01",
        {
          method: "GET",
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      if (!infoRes.ok || !activityRes.ok) {
        console.warn("API renvoie une erreur → fallback userData vide");
        setUserData({
          profile: {},
          statistics: {},
          sessions: [],
        });
        return;
      }

      const user = await infoRes.json();
      const sessions = await activityRes.json();

      // 🔥 Transformation complète (comme dans Profile.jsx)
      const transformed = transformUserData(user, sessions);

      // 🔥 On garde la structure attendue par Dashboard + Profile
      setUserData({
        profile: transformed.profile ?? {},
        statistics: transformed.statistics ?? {},
        sessions: transformed.sessions ?? [],
        // si transformUserData ajoute d'autres champs, on les garde
        ...transformed,
      });

    } catch (err) {
      console.error("Erreur UserContext :", err);

      // 🔥 fallback en cas d'erreur réseau
      setUserData({
        profile: {},
        statistics: {},
        sessions: [],
      });

    } finally {
      setLoading(false);
    }
  };

  fetchUserData();
}, [token]);


  return (
    <UserContext.Provider value={{ userData, loading }}>
      {children}
    </UserContext.Provider>
  );
};

export const useUser = () => useContext(UserContext);
